import { $getArray } from "../../WebGLUtil";
/**
 * @description 指定の座標とサイズで矩形を描画
 *              Draw a rectangle with the specified coordinates and size
 *
 * @param  {number} x
 * @param  {number} y
 * @param  {number} w
 * @param  {number} h
 * @return {array}
 * @method
 * @public
 */
export const execute = (x, y, w, h) => {
    return $getArray($getArray(x, y, false, x + w, y, false, x + w, y + h, false, x, y + h, false));
};
